"use client";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import Link from "next/link";
import { useParams, usePathname, useRouter } from "next/navigation";
import { Plus } from "lucide-react";
import { Fragment, useEffect, useState, type FormEvent, type ReactNode } from "react";
import { Button, buttonVariants } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import { client, sessionUser, type Inputs, type Outputs, type SessionUser } from "../client";
import { EmptyPane, ErrorNote, FieldRow, FormRow, ListSkeleton, OrderedList, Pagination, Pane, PaneHeader, PaneSkeleton, formatDateTime, selectClass, splitList, text } from "../ui";

type Row = Outputs["albums"]["list"]["data"][number];
type Detail = Outputs["albums"]["get"];
type Input<K extends keyof Inputs["albums"]> = Inputs["albums"][K];

const PAGE_SIZE = 20;
const KEY = ["albums"] as const;

function idOf(raw: string) {
  return raw;
}

function canCreate(user: SessionUser | null): boolean {
  return user !== null;
}

function canUpdate(user: SessionUser | null, row: Detail): boolean {
  return user !== null;
}

function canDelete(user: SessionUser | null, row: Detail): boolean {
  return user !== null;
}

const ALBUMS_FIELDS = ["artist_id", "title"] as const;
type AlbumsField = (typeof ALBUMS_FIELDS)[number];

type AlbumsValues = {
  artist_id: string;
  title: string;
};

const EMPTY_ALBUMS: AlbumsValues = {
  artist_id: "",
  title: ""
};

const ALBUMS_CREATE: readonly AlbumsField[] = ["artist_id", "title"];

function toAlbumsCreateInput(v: AlbumsValues): Input<"create"> {
  return {
    artist_id: v.artist_id,
    title: v.title
  };
}

const ALBUMS_UPDATE: readonly AlbumsField[] = ["artist_id", "title"];

function toAlbumsUpdateInput(v: AlbumsValues): Input<"update">["data"] {
  return {
    artist_id: v.artist_id,
    title: v.title
  };
}

function albumsFromRow(row: Detail): AlbumsValues {
  return {
    artist_id: text(row.artist_id),
    title: text(row.title)
  };
}

/** Picks a Artist from the artists resource */
function ArtistIdPicker({
  id,
  value,
  onChange,
  allowEmpty
}: {
  id: string;
  value: string;
  onChange: (value: string) => void;
  allowEmpty: boolean;
}) {
  const options = useQuery({ queryKey: ["artists", "list", { page_size: 200 }], queryFn: () => client.artists.list({ page_size: 200 }) });
  return (
    <select id={id} className={selectClass} value={value} onChange={e => onChange(e.target.value)}>
      {allowEmpty ? <option value="">—</option> : null}
      {(options.data?.data ?? []).map(item => (
        <option key={text(item.id)} value={text(item.id)}>
          {text(item.name)}
        </option>
      ))}
    </select>
  );
}

type AlbumsSetter = <K extends keyof AlbumsValues>(key: K, value: AlbumsValues[K]) => void;

function renderAlbumsField(field: AlbumsField, values: AlbumsValues, set: AlbumsSetter) {
  switch (field) {
    case "artist_id":
      return (
      <FormRow label="Artist" htmlFor="artist_id">
        <ArtistIdPicker id="artist_id" value={values.artist_id} onChange={value => set("artist_id", value)} allowEmpty={false} />
      </FormRow>
      );
    case "title":
      return (
      <FormRow label="Title" htmlFor="title">
        <Input id="title" type="text" maxLength={200} value={values.title} onChange={e => set("title", e.target.value)} required />
      </FormRow>
      );
  }
}

function AlbumsForm({
  fields,
  initial,
  submitLabel,
  pending,
  error,
  onSubmit,
  onCancel
}: {
  fields: readonly AlbumsField[];
  initial: AlbumsValues;
  submitLabel: string;
  pending: boolean;
  error: { message: string } | null;
  onSubmit: (values: AlbumsValues) => void;
  onCancel?: () => void;
}) {
  const [values, setValues] = useState<AlbumsValues>(initial);
  const [problem, setProblem] = useState<string | null>(null);
  const set: AlbumsSetter = (key, value) => setValues(current => ({ ...current, [key]: value }));
  const submit = (event: FormEvent) => {
    event.preventDefault();
    setProblem(null);
    try {
      onSubmit(values);
    } catch (err) {
      setProblem(err instanceof Error ? err.message : String(err));
    }
  };
  return (
    <form onSubmit={submit} className="grid max-w-xl gap-4">
      {fields.map(field => (
        <Fragment key={field}>{renderAlbumsField(field, values, set)}</Fragment>
      ))}
      <ErrorNote error={error ?? (problem ? { message: problem } : null)} />
      <div className="flex gap-2">
        <Button type="submit" disabled={pending}>
          {submitLabel}
        </Button>
        {onCancel ? (
          <Button type="button" variant="ghost" onClick={onCancel}>
            Cancel
          </Button>
        ) : null}
      </div>
    </form>
  );
}

export function AlbumsLayout({ children }: { children: ReactNode }) {
  const [page, setPage] = useState(1);
  const [openAction, setOpenAction] = useState<string | null>(null);
  void openAction;
  void setOpenAction;
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const input = { page, page_size: PAGE_SIZE } as Inputs["albums"]["list"];
  const list = useQuery({ queryKey: [...KEY, "list", input], queryFn: () => client.albums.list(input) });
  const pathname = usePathname();
  const queryClient = useQueryClient();

  return (
    <div className="flex h-full min-h-0">
      <aside className="flex w-80 shrink-0 flex-col border-r border-border">
        <PaneHeader title="Albums" count={list.data?.page.total}>
          {canCreate(user) ? (
            <Link href="/albums/new" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="New album">
              <Plus />
            </Link>
          ) : null}
        </PaneHeader>


        <div className="min-h-0 flex-1 overflow-y-auto">
          {list.isPending ? (
            <ListSkeleton />
          ) : list.error ? (
            <ErrorNote error={list.error} className="m-4" />
          ) : list.data.data.length === 0 ? (
            <EmptyPane>No albums yet.</EmptyPane>
          ) : (
            <ul className="py-1">
              {list.data.data.map((row: Row) => (
                <li key={text(row.id)}>
                  <Link
                    href={`/albums/${text(row.id)}`}
                    className={cn("block border-l-2 border-transparent px-4 py-2 hover:bg-accent/60", pathname === `/albums/${text(row.id)}` && "border-primary bg-accent")}
                  >
                    <div className="truncate text-sm font-medium">{text(row.title) || "Album " + text(row.id)}</div>
                    <div className="truncate text-xs text-muted-foreground">{[(row.artist ? text(row.artist.name) : text(row.artist_id))].filter(Boolean).join(" · ")}</div>
                  </Link>
                </li>
              ))}
            </ul>
          )}
        </div>
        {list.data ? <Pagination page={page} pageSize={PAGE_SIZE} total={list.data.page.total} onChange={setPage} /> : null}
      </aside>
      <section className="min-w-0 flex-1 overflow-y-auto">
        {children}
      </section>
    </div>
  );
}

export function AlbumsIndex() {
  return <EmptyPane>Select an album from the list, or create one.</EmptyPane>;
}

export function AlbumsNew() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const createRow = useMutation({
    mutationFn: (input: Input<"create">) => client.albums.create(input),
    onSuccess: async row => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push(`/albums/${text(row.id)}`);
    }
  });
  return (
    <Pane title="New album">
      <AlbumsForm
        fields={ALBUMS_CREATE}
        initial={EMPTY_ALBUMS}
        submitLabel="Create"
        pending={createRow.isPending}
        error={createRow.error}
        onSubmit={values => createRow.mutate(toAlbumsCreateInput(values))}
      />
    </Pane>
  );
}

/** The tracks of an album, in their order; a move goes through tracks.move, under its own rule */
function AlbumsTracksField({ row, user }: { row: Detail; user: SessionUser | null }) {
  void user;
  const queryClient = useQueryClient();
  const move = useMutation({
    mutationFn: (input: Inputs["tracks"]["move"]) => client.tracks.move(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: ["tracks"] });
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  return (
    <div>
      <OrderedList
        items={row.tracks} keyOf={item => text(item.id)} label={item => text(item.title)}
        onMove={user !== null ? (item, to) => move.mutate({ id: item.id, to }) : undefined}
        busy={move.isPending}
      />
      <ErrorNote error={move.error} className="mt-2" />
    </div>
  );
}

export function AlbumsDetail() {
  const { id: rawId } = useParams<{ id: string }>();
  const id = idOf(rawId);
  const router = useRouter();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  useEffect(() => {
    setEditing(false);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.albums.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["albums"]["update"]) => client.albums.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const removeRow = useMutation({
    mutationFn: (input: Inputs["albums"]["delete"]) => client.albums.delete(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push("/albums");
    }
  });

  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <ErrorNote error={query.error} className="m-6" />;
  const row: Detail = query.data;
  void row;
  return (
    <Pane
      title={text(row.title) || "Album " + text(row.id)}
      actions={
        <>
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
          {canDelete(user, row) ? (
            <Button
              variant="destructive"
              size="sm"
              disabled={removeRow.isPending}
              onClick={() => {
                if (window.confirm("Delete this album?")) removeRow.mutate({ id });
              }}
            >
              Delete
            </Button>
          ) : null}
        </>
      }
    >


      {editing ? (
        <AlbumsForm
          fields={ALBUMS_UPDATE}
          initial={albumsFromRow(row)}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: toAlbumsUpdateInput(values) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Id">{text(row.id) || "—"}</FieldRow>
        <FieldRow label="Artist">{(row.artist ? text(row.artist.name) : text(row.artist_id)) || "—"}</FieldRow>
        <FieldRow label="Title">{text(row.title) || "—"}</FieldRow>
        <FieldRow label="Created At">{formatDateTime(row.created_at) || "—"}</FieldRow>
        <FieldRow label="Tracks">
          <AlbumsTracksField row={row} user={user} />
        </FieldRow>
        </dl>
      )}
    </Pane>
  );
}
